
package dev.yinghuang.legacyforgebridge.repair322;
import com.google.gson.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;import org.objectweb.asm.commons.*;import java.util.*;import java.lang.reflect.*;import java.nio.charset.StandardCharsets;
import static org.objectweb.asm.Opcodes.*;import static dev.yinghuang.legacyforgebridge.repair322.CoreVisualPass322.*;
public final class ArmorCompiler323 {
 static final String ABI="dev/yinghuang/legacyforgebridge/repair322/ArmorAbi323";
 record Binding(String model,int part,float expansion){}
 static AbstractInsnNode origin(SourceValue value){if(value.insns.size()!=1)throw new IllegalArgumentException("ambiguous producer");return value.insns.iterator().next();}
 static Object constant(SourceValue v){AbstractInsnNode n=origin(v);int op=n.getOpcode();if(n instanceof LdcInsnNode l)return l.cst;if(n instanceof IntInsnNode i)return i.operand;if(op>=ICONST_M1&&op<=ICONST_5)return op-ICONST_0;if(op>=FCONST_0&&op<=FCONST_2)return (float)(op-FCONST_0);throw new IllegalArgumentException("nonconstant constructor operand");}
 static ClassNode findClientProxy(CoreVisualPass322 p,FieldInsnNode proxy){ClassNode c=p.classes.get(proxy.owner);if(c==null)throw new IllegalArgumentException("proxy owner absent");for(FieldNode f:c.fields)if(f.name.equals(proxy.name))for(List<AnnotationNode> list:Arrays.asList(f.visibleAnnotations,f.invisibleAnnotations))if(list!=null)for(AnnotationNode a:list)if(a.desc.equals("Lcpw/mods/fml/common/SidedProxy;"))for(int i=0;i<a.values.size();i+=2)if(a.values.get(i).equals("clientSide"))return p.classes.get(a.values.get(i+1).toString().replace('.','/'));throw new IllegalArgumentException("unproved client proxy");}
 static Binding bind(FeaturePass323 f,JsonObject item,int slot)throws Exception {
  String owner=item.get("sourceClass").getAsString();Object rm=f.method(owner,List.of("getArmorModel"),"(Lnet/minecraft/entity/EntityLivingBase;Lnet/minecraft/item/ItemStack;I)Lnet/minecraft/client/model/ModelBiped;");MethodNode m=(MethodNode)invoke(rm,"node");FieldInsnNode pf=null;MethodInsnNode query=null;for(AbstractInsnNode n:m.instructions){if(n instanceof FieldInsnNode q&&q.getOpcode()==GETSTATIC)pf=q;if(n instanceof MethodInsnNode q&&q.desc.equals("(I)Lnet/minecraft/client/model/ModelBiped;"))query=q;}
  if(pf==null||query==null)throw new IllegalArgumentException("armor model is not a slot-indexed proxy contract");ClassNode proxy=findClientProxy(f.p,pf);String queryName=query.name,queryDesc=query.desc;MethodNode getter=proxy.methods.stream().filter(x->x.name.equals(queryName)&&x.desc.equals(queryDesc)).findFirst().orElseThrow();FieldInsnNode array=null;for(AbstractInsnNode n:getter.instructions)if(n instanceof FieldInsnNode q&&q.getOpcode()==GETFIELD&&q.desc.equals("[Lnet/minecraft/client/model/ModelBiped;"))array=q;if(array==null)throw new IllegalArgumentException("proxy model array missing");
  List<Binding> matches=new ArrayList<>();for(MethodNode init:proxy.methods){if((init.access&(ACC_ABSTRACT|ACC_NATIVE))!=0)continue;Frame<SourceValue>[] frames;try{frames=new Analyzer<>(new SourceInterpreter()).analyze(proxy.name,init);}catch(Exception ignored){continue;}
   for(int i=0;i<init.instructions.size();i++)if(init.instructions.get(i).getOpcode()==AASTORE&&frames[i]!=null){Frame<SourceValue> frame=frames[i];int n=frame.getStackSize();try{AbstractInsnNode arr=origin(frame.getStack(n-3));if(!(arr instanceof FieldInsnNode field)||!field.name.equals(array.name)||!field.owner.equals(array.owner)||((Number)constant(frame.getStack(n-2))).intValue()!=slot)continue;
    for(AbstractInsnNode prev=init.instructions.get(i).getPrevious();prev!=null;prev=prev.getPrevious())if(prev instanceof MethodInsnNode call&&call.name.equals("<init>")&&call.desc.equals("(IF)V")){int at=init.instructions.indexOf(prev);Frame<SourceValue> before=frames[at];int size=before.getStackSize();int part=((Number)constant(before.getStack(size-2))).intValue();float expand=((Number)constant(before.getStack(size-1))).floatValue();if(part!=slot||expand<0||expand>2)throw new IllegalArgumentException("armor part mismatch");matches.add(new Binding(call.owner,part,expand));break;}
   }catch(IllegalArgumentException ignored){}}
  }if(matches.size()!=1)throw new IllegalArgumentException("model constructor binding count="+matches.size());return matches.getFirst();
 }
 static ArmorAbi323.Biped instantiate(CoreVisualPass322 p,Binding bind)throws Exception {
  LinkedHashMap<String,ClassNode> chain=new LinkedHashMap<>();String owner=bind.model;while(p.classes.containsKey(owner)){ClassNode c=p.classes.get(owner);chain.put(owner,c);owner=c.superName;}if(!owner.equals("net/minecraft/client/model/ModelBiped"))throw new IllegalArgumentException("not a vanilla biped constructor family");
  String token=sha(bind.model.getBytes(StandardCharsets.UTF_8)).substring(0,16);Map<String,String> map=new HashMap<>();map.put("net/minecraft/client/model/ModelBase",ABI+"$Base");map.put("net/minecraft/client/model/ModelBiped",ABI+"$Biped");map.put("net/minecraft/client/model/ModelRenderer",ABI+"$Part");int index=0;for(String s:chain.keySet())map.put(s,"dev/yinghuang/legacyforgebridge/generated/armor323/A"+token+"_"+(index++));
  Remapper mapper=new Remapper(){public String map(String s){return map.getOrDefault(s,s);}};Map<String,List<MethodNode>> methods=new LinkedHashMap<>();for(var e:chain.entrySet()){List<MethodNode> chosen=new ArrayList<>();for(MethodNode m:e.getValue().methods)if(m.name.equals("<init>"))chosen.add(m);methods.put(e.getKey(),chosen);}
  boolean changed;do{changed=false;for(var e:methods.entrySet())for(MethodNode m:List.copyOf(e.getValue()))for(AbstractInsnNode n:m.instructions){if(n instanceof JumpInsnNode j&&m.instructions.indexOf(j.label)<m.instructions.indexOf(n))throw new IllegalArgumentException("unbounded constructor loop");if(n instanceof InvokeDynamicInsnNode||n.getOpcode()==MONITORENTER||n.getOpcode()==PUTSTATIC)throw new IllegalArgumentException("nonvisual constructor effect");if(n instanceof TypeInsnNode t&&t.getOpcode()==NEW&&!t.desc.equals("net/minecraft/client/model/ModelRenderer"))throw new IllegalArgumentException("unapproved allocation "+t.desc);
   if(n instanceof MethodInsnNode q){if(chain.containsKey(q.owner)){MethodNode target=chain.get(q.owner).methods.stream().filter(v->v.name.equals(q.name)&&v.desc.equals(q.desc)).findFirst().orElse(null);if(target!=null&&!methods.get(q.owner).contains(target)){methods.get(q.owner).add(target);changed=true;}}else if(!map.containsKey(q.owner)||!Set.of("<init>","func_78789_a","func_78790_a","func_78793_a","func_78792_a","func_78784_a","func_78787_b").contains(q.name))throw new IllegalArgumentException("nonvisual constructor call "+q.owner+"."+q.name);}
  }}while(changed);
  Map<String,byte[]> bytes=new HashMap<>();for(var e:chain.entrySet()){ClassNode src=e.getValue();ClassWriter cw=new ClassWriter(ClassWriter.COMPUTE_FRAMES|ClassWriter.COMPUTE_MAXS){protected String getCommonSuperClass(String a,String b){return a.equals(b)?a:ABI+"$Part";}};cw.visit(V17,ACC_PUBLIC,map.get(src.name),null,mapper.map(src.superName),null);for(FieldNode field:src.fields){String desc=mapper.mapDesc(field.desc);if(desc.startsWith("L")&&!desc.equals("L"+ABI+"$Part;"))continue;cw.visitField(ACC_PUBLIC,field.name,desc,null,field.value).visitEnd();}for(MethodNode m:methods.get(src.name)){MethodVisitor mv=cw.visitMethod(ACC_PUBLIC,m.name,mapper.mapMethodDesc(m.desc),null,null);m.accept(new MethodRemapper(mv,mapper));}cw.visitEnd();bytes.put(map.get(src.name).replace('/','.'),cw.toByteArray());}
  ClassLoader loader=new ClassLoader(ArmorCompiler323.class.getClassLoader()){protected Class<?> findClass(String n)throws ClassNotFoundException{byte[] b=bytes.get(n);if(b==null)throw new ClassNotFoundException(n);return defineClass(n,b,0,b.length);}};
  return (ArmorAbi323.Biped)loader.loadClass(map.get(bind.model).replace('/','.')).getConstructor(int.class,float.class).newInstance(bind.part,bind.expansion);
 }
 static JsonObject part(ArmorAbi323.Part p,Set<ArmorAbi323.Part> seen){if(!seen.add(p))throw new IllegalArgumentException("cyclic armor hierarchy");JsonObject o=new JsonObject();o.add("pivot",G.toJsonTree(new float[]{p.field_78800_c,p.field_78797_d,p.field_78798_e}));o.add("rotation",G.toJsonTree(new float[]{p.field_78795_f,p.field_78796_g,p.field_78808_h}));o.addProperty("visible",p.field_78806_j&&!p.field_78807_k);o.add("boxes",G.toJsonTree(p.boxes));JsonArray a=new JsonArray();for(var c:p.children)a.add(part(c,seen));o.add("children",a);return o;}
 public static JsonObject capture(FeaturePass323 f,JsonObject item,int slot)throws Exception {Binding b=bind(f,item,slot);ArmorAbi323.Biped model=instantiate(f.p,b);JsonObject o=new JsonObject();o.addProperty("sourceModel",b.model);o.addProperty("sourcePart",b.part);o.addProperty("sourceExpansion",b.expansion);o.addProperty("textureWidth",model.field_78090_t);o.addProperty("textureHeight",model.field_78089_u);JsonObject roots=new JsonObject();Set<ArmorAbi323.Part> all=Collections.newSetFromMap(new IdentityHashMap<>());for(var e:model.roots().entrySet()){roots.add(e.getKey(),part(e.getValue(),all));}
  // Additional top-level ModelRenderer rendered after the standard biped (e.g. a separate waist piece).
  ClassNode src=f.p.classes.get(b.model);for(MethodNode m:src.methods)if(m.name.equals("func_78088_a"))for(AbstractInsnNode n:m.instructions)if(n instanceof FieldInsnNode field&&field.getOpcode()==GETFIELD&&field.desc.equals("Lnet/minecraft/client/model/ModelRenderer;")){try{Object p=model.getClass().getField(field.name).get(model);if(p instanceof ArmorAbi323.Part extra&&!all.contains(extra)){roots.add("body_extra_"+field.name,part(extra,all));}}catch(NoSuchFieldException ignored){}}
  o.add("roots",roots);System.out.println("SOURCE_BIPED "+item.get("id")+" model="+b.model+" bones="+all.size());return o;
 }
}
